void ACloudgardenController::BeginPlay(){Super::BeginPlay();bShowMouseCursor=true;SetInputMode(FInputModeGameAndUI());}
void ACloudgardenController::PlayerTick(float D){Super::PlayerTick(D);auto Mode=Cast<ACloudgardenMode>(GetWorld()->GetAuthGameMode());const bool Space=IsInputKeyDown(EKeys::SpaceBar),Right=IsInputKeyDown(EKeys::Right);if(Mode&&Space&&!WasSpace)Mode->SendCommand(Mode->Playing?TEXT("pause"):TEXT("play"));if(Mode&&Right&&!WasRight)Mode->SendCommand(TEXT("step"));WasSpace=Space;WasRight=Right;if(Mode&&WasInputKeyJustPressed(EKeys::P)){Mode->Plane=(Mode->Plane+1)%3;Mode->LastPayload.Empty();Mode->LoadSnapshot();}if(Mode&&WasInputKeyJustPressed(EKeys::M))Mode->MotionEnabled=!Mode->MotionEnabled;if(WasInputKeyJustPressed(EKeys::G)){ShowLibrary=!ShowLibrary;InspectorScroll=0;}if(ShowLibrary&&WasInputKeyJustPressed(EKeys::Up))CatalogIndex=FMath::Max(0,CatalogIndex-1);if(ShowLibrary&&WasInputKeyJustPressed(EKeys::Down))CatalogIndex++;if(Mode&&ShowLibrary&&WasInputKeyJustPressed(EKeys::C))Mode->CollectGene(CatalogIndex);if(WasInputKeyJustPressed(EKeys::I))ShowDetails=!ShowDetails;if(WasInputKeyJustPressed(EKeys::MouseScrollDown))InspectorScroll+=3;if(WasInputKeyJustPressed(EKeys::MouseScrollUp))InspectorScroll=FMath::Max(0,InspectorScroll-3);const bool Down=IsInputKeyDown(EKeys::LeftMouseButton);if(Down&&!WasDown){float X,Y;GetMousePosition(X,Y);int Width,Height;GetViewportSize(Width,Height);if(Mode&&Y<55&&X>Width-280){Mode->SendCommand(X>Width-110?TEXT("step"):(Mode->Playing?TEXT("pause"):TEXT("play")));}else {FHitResult Hit;if(GetHitResultUnderCursor(ECC_Visibility,false,Hit)){Selected=Cast<ACloudgardenPlant>(Hit.GetActor());if(!Selected&&Hit.GetActor())Selected=Cast<ACloudgardenPlant>(Hit.GetActor()->GetOwner());}}}WasDown=Down;}
ACloudgardenMode::ACloudgardenMode(){PrimaryActorTick.bCanEverTick=true;PlayerControllerClass=ACloudgardenController::StaticClass();HUDClass=ACloudgardenHUD::StaticClass();DefaultPawnClass=nullptr;}
void ACloudgardenMode::BeginPlay(){Super::BeginPlay();FString CatalogText;if(FFileHelper::LoadFileToString(CatalogText,*(FPaths::ProjectContentDir()/TEXT("Data/GeneCatalog.json")))){auto CatalogReader=TJsonReaderFactory<>::Create(CatalogText);FJsonSerializer::Deserialize(CatalogReader,Catalog);}auto Camera=GetWorld()->SpawnActor<ACameraActor>();Camera->SetActorLocation(FVector(2200,-2200,2500));Camera->SetActorRotation((FVector(0,0,0)-Camera->GetActorLocation()).Rotation());Camera->GetCameraComponent()->ProjectionMode=ECameraProjectionMode::Orthographic;Camera->GetCameraComponent()->OrthoWidth=1400;GetWorld()->GetFirstPlayerController()->SetViewTarget(Camera);auto Light=GetWorld()->SpawnActor<ADirectionalLight>();Light->SetActorRotation(FRotator(-55,-30,0));Light->GetLightComponent()->SetIntensity(5);GetWorld()->SpawnActor<ASkyLight>();LoadSnapshot();if(auto PC=Cast<ACloudgardenController>(GetWorld()->GetFirstPlayerController());PC&&IsValid(PC->Selected)){FVector Target=PC->Selected->ExactAnchor+FVector(0,0,100);Camera->SetActorLocation(Target+FVector(1200,-1200,1250));Camera->SetActorRotation((Target-Camera->GetActorLocation()).Rotation());}GetWorldTimerManager().SetTimer(RefreshTimer,this,&ACloudgardenMode::LoadSnapshot,1,true);}
void ACloudgardenMode::SendCommand(const FString& Action){Playing=Action==TEXT("play")?true:Action==TEXT("pause")?false:Playing;const int64 Id=FDateTime::UtcNow().GetTicks();const FString Path=GardenDataDir()/TEXT("CloudgardenCommands.json");const FString Json=FString::Printf(TEXT("{\"id\":%lld,\"action\":\"%s\",\"days\":1}"),Id/10000,*Action);if(FFileHelper::SaveStringToFile(Json,*(Path+TEXT(".tmp"))))IFileManager::Get().Move(*Path,*(Path+TEXT(".tmp")),true);}
// Reuse native geometry by render slot: memory follows the maximum simultaneous garden, never elapsed days.
static TArray<AActor*> ShapePool;
static TArray<ACloudgardenPlant*> BotanicalPool;
static int ShapeCursor=0, BotanicalCursor=0;
static ACloudgardenPlant* BotanicalActor(UWorld* World){ACloudgardenPlant* Plant=nullptr;if(BotanicalPool.IsValidIndex(BotanicalCursor)&&IsValid(BotanicalPool[BotanicalCursor])&&BotanicalPool[BotanicalCursor]->GetWorld()==World)Plant=BotanicalPool[BotanicalCursor];else{Plant=World->SpawnActor<ACloudgardenPlant>();if(BotanicalPool.IsValidIndex(BotanicalCursor))BotanicalPool[BotanicalCursor]=Plant;else BotanicalPool.Add(Plant);}BotanicalCursor++;Plant->SetActorHiddenInGame(false);Plant->Mesh->SetCollisionEnabled(ECollisionEnabled::QueryOnly);return Plant;}
static AActor* Shape(UWorld* World,TArray<AActor*>& Store,const FVector& Location,const FVector& Scale,const TCHAR* Asset,const FLinearColor& Color){AActor* Actor=nullptr;UStaticMeshComponent* Mesh=nullptr;if(ShapePool.IsValidIndex(ShapeCursor)&&IsValid(ShapePool[ShapeCursor])&&ShapePool[ShapeCursor]->GetWorld()==World){Actor=ShapePool[ShapeCursor];Mesh=Cast<UStaticMeshComponent>(Actor->GetRootComponent());}else{Actor=World->SpawnActor<AActor>();Mesh=NewObject<UStaticMeshComponent>(Actor);Actor->SetRootComponent(Mesh);Mesh->RegisterComponent();if(ShapePool.IsValidIndex(ShapeCursor))ShapePool[ShapeCursor]=Actor;else ShapePool.Add(Actor);}ShapeCursor++;Mesh->SetStaticMesh(LoadObject<UStaticMesh>(nullptr,Asset));Actor->SetActorHiddenInGame(false);Actor->SetOwner(nullptr);Actor->SetActorRotation(FRotator::ZeroRotator);ColorMesh(Mesh,Color);Mesh->SetCollisionEnabled(ECollisionEnabled::NoCollision);Actor->SetActorLocation(Location);Actor->SetActorScale3D(Scale);Store.Add(Actor);return Actor;}
static void Segment(UWorld* World,TArray<AActor*>& Store,const FVector& A,const FVector& B,float Radius,const FLinearColor& Color){auto Actor=Shape(World,Store,(A+B)*.5,FVector(Radius,Radius,FVector::Dist(A,B)/100),TEXT("/Engine/BasicShapes/Cylinder.Cylinder"),Color);Actor->SetActorRotation(FQuat::FindBetweenNormals(FVector::UpVector,(B-A).GetSafeNormal()));}
void ACloudgardenMode::Tick(float Delta){Super::Tick(Delta);for(auto& F:Flights){if(!IsValid(F.Actor))continue;if(!MotionEnabled){F.Actor->SetActorLocation(F.To);continue;}F.Age+=Delta;float T=FMath::Clamp(F.Age/1.8f,0.f,1.f);F.Actor->SetActorLocation(FMath::Lerp(F.From,F.To,T)+FVector(0,0,FMath::Sin(T*PI)*90));}}
void ACloudgardenMode::CollectGene(int Index){const TArray<TSharedPtr<FJsonValue>>* Genes;if(!Catalog.IsValid()||!Catalog->TryGetArrayField(TEXT("genes"),Genes)||!Genes->IsValidIndex(Index))return;FString Text;TSharedPtr<FJsonObject> Collection=MakeShared<FJsonObject>();const FString Path=GardenDataDir()/TEXT("GeneCollection.json");if(FFileHelper::LoadFileToString(Text,*Path)){auto Reader=TJsonReaderFactory<>::Create(Text);FJsonSerializer::Deserialize(Reader,Collection);}TArray<TSharedPtr<FJsonValue>> Entries;const TArray<TSharedPtr<FJsonValue>>* Existing;if(Collection->TryGetArrayField(TEXT("genes"),Existing))Entries=*Existing;const FString Id=Str((*Genes)[Index]->AsObject(),TEXT("id"));for(auto Value:Entries)if(Str(Value->AsObject(),TEXT("id"))==Id){Status=TEXT("Gen ist bereits in deiner lokalen Sammlung.");return;}Entries.Add((*Genes)[Index]);Collection->SetArrayField(TEXT("genes"),Entries);Text.Empty();auto Writer=TJsonWriterFactory<>::Create(&Text);FJsonSerializer::Serialize(Collection.ToSharedRef(),Writer);FFileHelper::SaveStringToFile(Text,*Path);Status=TEXT("Einzelnes Gen lokal gesammelt. Dokumentation, keine Code-Ausfuehrung.");}
